// Top-down exploration layered over the three original algorithm activities.
const puzzle1=show1,puzzle2=show2,puzzle3=show3;let world=1,px=110,py=285,worldActive=false,dialogOpen=false,modalOpen=false,near=null,frameId=0,last=0,keys={},talked=false;
const scenes={1:{name:'Аудитория QAIRU',objective:'Поговори с другом, затем почини электрощиток у выхода.',objects:[{x:280,y:270,label:'Друг',kind:'friend'},{x:700,y:250,label:'Электрощиток',kind:'terminal'},{x:138,y:130,label:'Ноутбук',kind:'laptop'}]},2:{name:'Вечерняя Астана',objective:'Подойди к навигатору и построй маршрут до EXPO.',objects:[{x:315,y:250,label:'Остановка',kind:'friend'},{x:650,y:235,label:'Навигатор',kind:'terminal'},{x:160,y:165,label:'Сообщение',kind:'phone'}]},3:{name:'Серверная EXPO',objective:'Подойди к терминалу, изучи улики и выбери подозреваемого.',objects:[{x:620,y:235,label:'Терминал улик',kind:'terminal'},{x:300,y:300,label:'SANA',kind:'sana'},{x:150,y:155,label:'Заметка',kind:'phone'}]}};
start=function(){world=1;clues=[];solved=false;route=null;talked=false;enterWorld(1)};
show2=function(){closeModal();enterWorld(2)};show3=function(){closeModal();enterWorld(3)};
function enterWorld(n){world=n;chapter=n;px=100;py=310;keys={};worldActive=true;dialogOpen=false;modalOpen=false;cancelAnimationFrame(frameId);root.innerHTML=`<div class="world-wrap"><div class="world-head"><div><div class="chapter">ЭПИЗОД 0${n} / 03 · ${scenes[n].name.toUpperCase()}</div><h1>Последний сигнал Астаны</h1><p>Исследуй локацию и взаимодействуй с окружающими.</p></div><span class="tag">ИСТОРИЯ В ПРОЦЕССЕ</span></div><div class="world-grid"><div><div class="world-screen"><canvas id="world" width="800" height="440" aria-label="Игровая сцена: используй стрелки или WASD, чтобы ходить, и E, чтобы взаимодействовать"></canvas><div id="near" class="near" hidden></div><div id="speech" class="speechbox" hidden></div></div><div class="touch-controls"><button aria-label="Влево" data-key="ArrowLeft">◀</button><button aria-label="Вверх" data-key="ArrowUp">▲</button><button aria-label="Вниз" data-key="ArrowDown">▼</button><button aria-label="Вправо" data-key="ArrowRight">▶</button><button id="touch-action">ДЕЙСТВИЕ · E</button></div></div><aside class="world-side"><div class="eyebrow">ТВОЯ МИССИЯ</div><h3>${scenes[n].name}</h3><div class="missionbox">${scenes[n].objective}</div><div class="world-info">⌨️ <b>WASD / стрелки</b> — движение<br>✋ <b>E</b> — поговорить или осмотреть<br>🤖 QairuBot всегда рядом</div><p>Подходи к отмеченным предметам и людям. Учебная карта и события вымышлены.</p></aside></div></div>`;document.querySelectorAll('[data-key]').forEach(b=>{let key=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[key]=true});b.addEventListener('pointerup',()=>keys[key]=false);b.addEventListener('pointercancel',()=>keys[key]=false)});document.getElementById('touch-action').onclick=interact;last=0;frameId=requestAnimationFrame(loop);if(n===1)showSpeech('QAIRUBOT','Завтра файнал, а у нас пропал Wi-Fi. Нормальное начало студенческого вечера. Подойди к другу и нажми E.')}
frame=function(n,title,loc,story,quote,content){modalOpen=true;keys={};let wrap=document.createElement('div');wrap.id='modal';wrap.className='game-modal';wrap.innerHTML=`<section class="panel"><button class="close-game" onclick="closeModal()">✕ Вернуться</button>${content}</section>`;document.body.appendChild(wrap)};
function closeModal(){document.getElementById('modal')?.remove();modalOpen=false;keys={}}
function showSpeech(who,text){if(!worldActive)return;dialogOpen=true;keys={};let s=document.getElementById('speech');s.hidden=false;s.innerHTML=`<b>${who}</b>${text}<br><button class="secondary" onclick="closeSpeech()">ДАЛЕЕ ↗</button>`}function closeSpeech(){dialogOpen=false;document.getElementById('speech').hidden=true}
function interact(){if(!worldActive||modalOpen)return;if(dialogOpen){closeSpeech();return}if(!near)return;let kind=near.kind;if(world===1&&kind==='friend'){talked=true;showSpeech('ДРУГ ИЗ QAIRU','Бро, я только начал понимать Байеса… Свет моргнул! Дверь заблокирована. Восстановим питание: подойди к щитку у выхода.');return}if(kind==='terminal'){if(world===1&&!talked){showSpeech('QAIRUBOT','Сначала поговори с другом — он видел, что произошло.');return}if(world===1)puzzle1();if(world===2)puzzle2();if(world===3)puzzle3();return}if(kind==='laptop')showSpeech('НОУТБУК','На экране: «SANA отключена. Файнал не отменили. Помогите». Очень заботливая система.');if(kind==='phone')showSpeech('СООБЩЕНИЕ',world===2?'Друг: «Я бы помог, но я уже в общаге и снял носки».':'Записка: «Не обвиняйте никого, пока не проверите улики».');if(kind==='sana')showSpeech('SANA','Сигнал слабый. Кто-то отключил мою проверку безопасности. Найдите записи на терминале.')}
function rounded(c,x,y,w,h,r,fill){c.fillStyle=fill;c.beginPath();c.roundRect(x,y,w,h,r);c.fill()}function label(c,text,x,y){c.font='bold 11px Arial';let w=c.measureText(text).width+18;rounded(c,x-w/2,y-30,w,20,5,'#071820dc');c.fillStyle='#e2f4e6';c.textAlign='center';c.fillText(text,x,y-16)}
function drawRoom(c,t){if(world===1){c.fillStyle='#6a8790';c.fillRect(0,0,800,440);c.fillStyle='#304e5b';c.fillRect(0,0,800,90);c.fillStyle='#d0a46f';c.fillRect(0,90,800,350);for(let x=0;x<800;x+=70){c.strokeStyle='#b98b5f';c.beginPath();c.moveTo(x,90);c.lineTo(x,440);c.stroke()}rounded(c,35,15,255,52,4,'#193d46');c.fillStyle='#c2e9c6';c.font='bold 19px Arial';c.textAlign='left';c.fillText('QAIRU  /  AI FUNDAMENTALS',50,47);for(let x=80;x<=440;x+=180){rounded(c,x,155,120,55,6,'#8a6044');rounded(c,x+10,160,100,35,3,'#ddb583')}rounded(c,635,24,98,68,4,'#223e4a');rounded(c,650,34,68,58,4,'#1b3440');c.fillStyle='#c5f276';c.fillRect(712,58,5,6)}else if(world===2){c.fillStyle='#94afbb';c.fillRect(0,0,800,440);c.fillStyle='#213e4d';c.fillRect(0,0,800,135);for(let x=30;x<800;x+=90){let h=40+(x%3)*12;c.fillStyle='#315767';c.fillRect(x,115-h,58,h);c.fillStyle='#d9b96f';for(let j=0;j<4;j++)c.fillRect(x+8+j*12,93-h,5,6)}c.fillStyle='#dbeced';c.fillRect(0,135,800,305);c.fillStyle='#677c83';c.fillRect(0,275,800,105);c.strokeStyle='#f3e5bb';c.setLineDash([22,18]);c.beginPath();c.moveTo(0,329);c.lineTo(800,329);c.stroke();c.setLineDash([]);c.fillStyle='#d7e8e9';for(let i=0;i<45;i++){let x=(i*131+t*.025*(i%3+1))%800,y=(i*71+t*.04*(i%4+1))%440;c.fillRect(x,y,2,3)}rounded(c,225,150,160,100,5,'#4a7580');rounded(c,235,160,140,73,4,'#b2d8d8');c.fillStyle='#e7f6f0';c.font='bold 14px Arial';c.textAlign='left';c.fillText('ASTANA · EXPO →',240,200)}else{c.fillStyle='#233f4c';c.fillRect(0,0,800,440);c.fillStyle='#102935';c.fillRect(0,0,800,110);for(let x=35;x<770;x+=92){rounded(c,x,28,65,140,5,'#172d37');for(let y=40;y<150;y+=20){rounded(c,x+8,y,48,11,2,'#345a61');c.fillStyle='#8df6be';c.fillRect(x+47,y+3,3,3)}}for(let x=0;x<800;x+=55){c.strokeStyle='#34515b';c.beginPath();c.moveTo(x,180);c.lineTo(x,440);c.stroke()}c.fillStyle='#d0e9dc';c.font='bold 18px Arial';c.fillText('EXPO / SANA NETWORK',300,205)}}
function character(c,x,y,color,robot=false,t=0){c.save();c.translate(x,y);c.fillStyle='#00131a77';c.beginPath();c.ellipse(0,15,18,7,0,0,Math.PI*2);c.fill();if(robot){rounded(c,-13,-19+Math.sin(t/400)*2,26,23,8,'#e6f5ef');rounded(c,-9,-16+Math.sin(t/400)*2,18,12,5,'#1b6673');c.fillStyle='#94fff0';c.fillRect(-6,-12,3,3);c.fillRect(3,-12,3,3)}else{rounded(c,-12,-15,24,25,7,color);rounded(c,-9,5,7,13,3,'#142732');rounded(c,2,5,7,13,3,'#142732');c.fillStyle='#e4b28d';c.beginPath();c.arc(0,-23,11,0,Math.PI*2);c.fill();c.fillStyle='#1c2930';c.beginPath();c.arc(0,-27,10,Math.PI,0);c.fill()}c.restore()}
function loop(t){if(!worldActive||!document.getElementById('world'))return;let dt=Math.min((t-(last||t))/1000,.05);last=t;if(!dialogOpen&&!modalOpen){let x=(keys.ArrowRight||keys.d||keys.D?1:0)-(keys.ArrowLeft||keys.a||keys.A?1:0),y=(keys.ArrowDown||keys.s||keys.S?1:0)-(keys.ArrowUp||keys.w||keys.W?1:0);let len=Math.hypot(x,y)||1;px=Math.max(24,Math.min(776,px+x/len*170*dt));py=Math.max(115,Math.min(410,py+y/len*170*dt))}let c=document.getElementById('world').getContext('2d');drawRoom(c,t);for(const o of scenes[world].objects){if(o.kind==='friend')character(c,o.x,o.y,'#c68d63');else if(o.kind==='sana'){c.fillStyle='#60d7cb';c.beginPath();c.arc(o.x,o.y-10,24,0,Math.PI*2);c.fill();c.fillStyle='#103c46';c.beginPath();c.arc(o.x,o.y-10,17,0,Math.PI*2);c.fill()}else{rounded(c,o.x-22,o.y-27,44,35,5,o.kind==='terminal'?'#285560':'#365861');rounded(c,o.x-16,o.y-22,32,22,2,'#8ce3cd')}label(c,o.label,o.x,o.y-30)}character(c,px-35,py+14,'',true,t);character(c,px,py,'#58a2a0');label(c,'ТЫ',px,py-35);near=scenes[world].objects.filter(o=>Math.hypot(o.x-px,o.y-py)<70).sort((a,b)=>Math.hypot(a.x-px,a.y-py)-Math.hypot(b.x-px,b.y-py))[0]||null;let hint=document.getElementById('near');hint.hidden=!near||dialogOpen||modalOpen;if(near)hint.textContent=`E · ${near.label}`;frameId=requestAnimationFrame(loop)}
document.addEventListener('keydown',e=>{if(!worldActive)return;if(modalOpen)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key.toLowerCase()==='e'&&!e.repeat){interact();return}keys[e.key]=true});document.addEventListener('keyup',e=>keys[e.key]=false);window.addEventListener('blur',()=>keys={});
const oldFinish=finish;finish=function(){let s=document.getElementById('suspect');if(!s||s.value===''){oldFinish();return}worldActive=false;cancelAnimationFrame(frameId);oldFinish();closeModal()};
